import static org.junit.Assert.assertEquals;

/**
 * Unit tests for StringEscapeUtils.escapeJava(Writer out, String str)
 */
public class StringEscapeUtils_escapeJava_TriageGen2Test {







    @Test
    public void testEscapeJava_SpecialCharacters() throws IOException {
        StringWriter out = new StringWriter();
        StringEscapeUtils.escapeJava(out, "Hello\nWorld\t\"Quotes\"\\Backslash");
        // \n becomes \\n, \t becomes \\t, \" becomes \\\", \\ becomes \\\\
        assertEquals("Hello\\nWorld\\t\\\"Quotes\\\"\\\\Backslash", out.toString());
    }








}

