package org.apache.commons.lang;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.exception.NestableRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for StringEscapeUtils.escapeJava(Writer out, String str)
 */
public class StringEscapeUtils_escapeJava_TriageGen2Test {















    @Test
    public void testEscapeJava_IOException() throws IOException {
        // Custom Writer to simulate IOException
        class ThrowingWriter extends java.io.Writer {
            @Override
            public void write(char[] cbuf, int off, int len) throws IOException {
                throw new IOException("Simulated IO Error");
            }

            @Override
            public void flush() throws IOException {}

            @Override
            public void close() throws IOException {}
        }

        ThrowingWriter writer = new ThrowingWriter();
        try {
            StringEscapeUtils.escapeJava(writer, "test");
            org.junit.Assert.fail("Should have thrown IOException");
        } catch (IOException e) {
            assertEquals("Simulated IO Error", e.getMessage());
        }
    }
}
